INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (105, 195, 'Cast polypropylene film (CPP Film)', '../upload/image/20181226/20181226141426_40443.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">Cast polypropylene film (CPP Film)</span></p> <p><span style="color:#009900;font-family:Verdana;">CPP film (cast polypropylene film) known as polypropylene film does not stretch, according to different uses can be divided into general CPP (General CPP. Referred to as the GCPP) film. Aluminum Level CPP (Metalize CPP, referred to as MCPP) film and cooking class CPP (Retort CPP referred RCPP) films. CPP film is got by the method of casting non- oriented polypropylene film.</span><br/> <span style="color:#009900;font-family:Verdana;"> CPP film (cast Polypropylene film) included plain/general cast PP film,Retort cast polypropylene film, cpp laminating film,cpp packing film,VMCPP film, white twist CPP packing materials </span><br/> <span style="color:#009900;font-family:Verdana;"> 1, (lamination film-CPP film ) clothing, knitwear and flower bags; files and albums films; food packaging.</span><br/> <span style="color:#009900;font-family:Verdana;"> 2, (aluminized-CPP film) barrier packaging and metal-film packing. After vacuum aluminum, laminating with BOPP, BOPA and other substrate materials used for composite and tea, crispy fried foods, biscuits and other high-grade packaging.</span><br/> <span style="color:#009900;font-family:Verdana;"> 3, (cooking film-CPP film) CPP excellent heat resistance. The softening point of PP is about 140C, such films can be used in hot filling, cooking bags, aseptic packaging and other fields. With acid and alkali resistance, excellent performance grease, making bread or laminated packaging material of choice for the field of materials.</span><br/> <span style="color:#009900;font-family:Verdana;"> 4, (function film, also called special film-CPP film ) usage and application include: food packaging, candy packaging (twist), pharmaceutical packaging (infusion bag), in albums, folders and files and other fields instead of PVC, synthetic paper, adhesive tape, business card holder, ring stand bags of folders and composite materials.</span><br/> <span style="color:#009900;font-family:Verdana;"> 5, the specifications are: Thickness:20-150 microns (UM), width :350-1500MM, length :2000-6000M </span><br/> <span style="color:#009900;font-family:Verdana;"> CPP film has good transparency, high gloss, good stiffness, good wet resistance, heat resistance and excellent, easy-to-heat sealing characteristics.</span><br/> <span style="color:#009900;font-family:Verdana;"> After printed, CPP film is suitable for bag, garments, knitwear and flower bags; files and albums films; food packaging; barrier packaging and decoration of the metal film.</span><br/> <span style="color:#009900;font-family:Verdana;"> 6. CPP white twist film Cpp white twist candy wrap film,with sizes: </span><br/> <span style="color:#009900;font-family:Verdana;"> thickness is 30 microns,The width are two, 480 mm and 960 mm,The length could be about 6000 mts</span><br/> <span style="color:#009900;font-family:Verdana;"> The core diameter: 3 inches, CPP white film included CPP white twist film, CPP white film,cast white Polypropylene film, cast PP film twist</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (105, 434, 'Retort cast polypropylene film (CPP)', '../upload/image/20211231/20211231131502_39827.jpg', '<p><span style="color:#009688;font-family:&quot;font-size:14px;background-color:#F2F2F2;">Retort cast polypropylene film (CPP)</span></p>', '2026-09-06 20:58:45');